    let mut modifier = None;
    if cursor.peek() == Some(b';') {
        cursor.next();
        modifier = Some(cursor.parse_digits(1)?);
    }
    let mut event = None;
    if cursor.peek() == Some(b':') {
        cursor.next();
        event = Some(cursor.parse_digits(1)?);
    }
    if cursor.next() != Some(b'u') || !cursor.at_end() {
