        3 => FUNCTIONAL_DELETE,
        5 => FUNCTIONAL_PAGE_UP,
        6 => FUNCTIONAL_PAGE_DOWN,
        7 => FUNCTIONAL_HOME,
        8 => FUNCTIONAL_END,
        _ => return None,
