    let modifier = cursor.parse_digits(1)? - 1;
    let mut event = None;
    if cursor.peek() == Some(b':') {
        cursor.next();
        event = Some(cursor.parse_digits(1)?);
    }
    let codepoint = match cursor.next()? {
        b'H' => FUNCTIONAL_HOME,
        b'F' => FUNCTIONAL_END,
        _ => return None,
    };
    if !cursor.at_end() {
        return None;
    }
    Some(ParsedKittySequence {
        codepoint,
        shifted_key: None,
        base_layout_key: None,
        modifier,
        event_type: parse_event_type(event),
