// Global Keybinding Registry
// =============================================================================

static GLOBAL_KEYBINDINGS: OnceLock<RwLock<KeybindingsManager>> = OnceLock::new();

/// Install the global keybinding manager (`setKeybindings`, keybindings.ts:235-237).
///
/// Upstream replaces the singleton unconditionally; here the first install
/// wins — once [`get_keybindings`] has initialized the global (or a previous
/// `set_keybindings` installed an instance), later installs are ignored.
/// Every upstream flow installs before any component reads the singleton and
/// re-installs reuse the same instance, so the observable behaviour is
/// identical.
pub fn set_keybindings(keybindings: KeybindingsManager) {
    let _ = GLOBAL_KEYBINDINGS.set(RwLock::new(keybindings));
}

/// The global keybinding manager, lazily created from the default table when
/// not installed (`getKeybindings`, keybindings.ts:239-243).
///
/// Components use the shared registry like upstream
/// `getKeybindings().matches(...)`:
///
/// ```
/// let read = pir_tui::keybindings::get_keybindings()
///     .read()
///     .unwrap_or_else(|poisoned| poisoned.into_inner());
/// ```
pub fn get_keybindings() -> &'static RwLock<KeybindingsManager> {
    GLOBAL_KEYBINDINGS.get_or_init(|| RwLock::new(KeybindingsManager::with_defaults()))
}

