import re

ts = open('external/pi/packages/tui/src/keys.ts').read()
rs = open('crates/pir-tui/src/keys.rs').read()

def parse_list(s):
    out=[]
    for it in s.split(','):
        it=it.strip().strip('"')
        if it: out.append(it)
    return out

def ts_table(tbl):
    m = re.search(r'const ' + tbl + r' = \{(.*?)\} as const;', ts, re.S)
    return {k: parse_list(v) for k,v in re.findall(r'(\w+): \[([^\]]*)\]', m.group(1))}

def rs_table(fn):
    m = re.search(r'fn ' + fn + r'\(key: &str\)[^{]*\{(.*?)\n\}', rs, re.S)
    return {k: parse_list(v) for k,v in re.findall(r'"(\w+)" => &\[([^\]]*)\]', m.group(1))}

pairs = [('LEGACY_KEY_SEQUENCES','legacy_key_sequences'),
         ('LEGACY_SHIFT_SEQUENCES','legacy_shift_sequences'),
         ('LEGACY_CTRL_SEQUENCES','legacy_ctrl_sequences')]
ok=True
for tname, rname in pairs:
    td = ts_table(tname); rd = rs_table(rname)
    if set(td)!=set(rd):
        print(tname,'KEY SET MISMATCH', set(td)^set(rd)); ok=False
    for k in sorted(td):
        if td[k]!=rd.get(k):
            print(tname,'MISMATCH',k,td[k],'!=',rd.get(k)); ok=False
    print(tname, 'OK' if ok and set(td)==set(rd) else 'DIFFERS', len(td), len(rd))

